"""A process-local, per-stream LRU; never reads or writes the filesystem."""
from collections import OrderedDict


class SnapshotCache:
    def __init__(self, slots):
        self.slots = slots
        self.entries = OrderedDict()

    def get(self, key):
        if key not in self.entries:
            return None
        value = self.entries[key]
        self.entries.move_to_end(key)
        return value

    def put(self, key, certificate):
        if not self.slots:
            return
        self.entries[key] = certificate
        self.entries.move_to_end(key)
        if len(self.entries) > self.slots:
            self.entries.popitem(last=False)
